function c(){const e=document.getElementById("burger-toggle"),n=document.querySelector(".menu"),o=document.body,s=document.documentElement;if(!e||!n){console.warn("burgerToggle or menu not found");return}e.addEventListener("change",function(){e.checked?(o.classList.add("no-scroll"),s.classList.add("no-scroll")):(o.classList.remove("no-scroll"),s.classList.remove("no-scroll"))}),window.addEventListener("resize",()=>{window.innerWidth>768&&e.checked&&(e.checked=!1,o.classList.remove("no-scroll"),s.classList.remove("no-scroll"))}),n.addEventListener("click",()=>{e.checked=!1,o.classList.remove("no-scroll"),s.classList.remove("no-scroll")})}export{c as i};
